const fs=require('fs');
const report=JSON.parse(fs.readFileSync('/private/tmp/localos-current-source-scan-20260921.8KYNaW/findings-redacted.json')), prefix='/private/tmp/localos-current-source-scan-20260921.8KYNaW/source/';
const digestFiles=new Set(['.agent/tasks/localos-plan-20260906/evidence.json','.agent/tasks/localos-plan-20260906/raw/frontend-production-build-proof.json','outputs/localos-release-20260905/manifest.json','outputs/localos-release-20260905/production-final-manifest.json','outputs/localos-release-20260906/release-manifest.json']);
const escape=value=>value.replace(/[.*+?^$\{\}()|[\]\\]/g,'\\$&');
const checks=[];
for(const row of report) {
 const file=row.File.slice(prefix.length);
 if(!digestFiles.has(file)) continue;
 const region=fs.readFileSync(row.File,'utf8').split('\n').slice(row.StartLine-1,row.EndLine).join('\n');
 const pattern=row.Match.split('REDACTED').map(escape).join('([0-9a-f]{64})');
 checks.push({file,line:row.StartLine,sha256_value_shape:new RegExp(pattern).test(region)});
}
const wordstat=fs.readFileSync(prefix+'docs/legacy/WORDSTAT_SETUP.md','utf8');
const placeholder=/Authorization:\s*Bearer\s+your_session_token["\s]/.test(wordstat);
console.log(JSON.stringify({hash_findings:checks.length,all_hash_values_match:checks.every(item=>item.sha256_value_shape),checks,wordstat_bearer_is_literal_placeholder:placeholder},null,2));
process.exitCode=checks.length===83 && checks.every(item=>item.sha256_value_shape) && placeholder ? 0 : 1;

